// Geometric straight-stitch embroidery font for Chinese characters & punctuation.
// Stitches match hand-embroidered letters on linen weave: clean straight needle stitches,
// crisp box structures (田, 日, 口), straight diagonal needle slashes, and natural needle holes.

const glyph = (width, strokes) => ({ width, strokes });
const decode = value => value.split('|').map(stroke => stroke.split(' ').map(pair => pair.split(',').map(Number)));
const g = (width, value) => glyph(width, decode(value));

